-- ----------------------------
-- Table structure for t_ticket_detail
-- ----------------------------
DROP TABLE IF EXISTS `t_ticket_detail`;
CREATE TABLE `t_ticket_detail` (
  `id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键id',
  `prefix` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '前缀',
  `cargo_no` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单号',
  `ticket_type` tinyint(1) NOT NULL COMMENT '票据类型,1: 货单, 2: 邮单',
  `stock_state` tinyint NOT NULL COMMENT '票证状态, 1: 未分配, 2: 已分配,3: 已使用, 4: 已核销，5:已作废',
  `international` tinyint NOT NULL COMMENT '国内国际, 1: 国内, 2: 国际',
  `used_unit` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '领用单位, 按要求代理人要存代理人编码，不能存id，所以当前字段外站存的是id，代理人存的是编码',
  `used_unit_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '领用单位名称',
  `unit_type` tinyint DEFAULT NULL COMMENT '单位类型, 1: 总部或者外站,  2: 代理人',
  `assign_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '分配人名称',
  `assign_time` datetime DEFAULT NULL COMMENT '分配时间',
  `stock_time` datetime DEFAULT NULL COMMENT '入库时间',
  `stock_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '入库人名称',
  `receive_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '领票人名称',
  `check_time` timestamp NULL DEFAULT NULL COMMENT '核销时间',
  `check_by` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '核销人名称',
  `cancel_state` tinyint(1) DEFAULT NULL COMMENT '核销前的状态',
  `is_delete` tinyint(1) DEFAULT '0' COMMENT '是否删除 0：未删除 1：删除',
  `invalid_state` tinyint(1) DEFAULT NULL COMMENT '作废状态 ，0：待审批，1：已通过，2：已驳回',
  `business_state` tinyint(1) DEFAULT NULL COMMENT '业务状态，0：未使用，1：已订舱，2：已批舱，3：已制单',
  `refuse_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '驳回原因',
  `create_time` timestamp NULL DEFAULT NULL COMMENT '创建时间',
  `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人名称',
  `update_time` timestamp NULL DEFAULT NULL COMMENT '更新时间',
  `agent_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '代理人编码',
  `financial_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '代理人财务代码(票证模块用不到，用于其他服务)',
  `invalid_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '驳回作废原因',
  `dept_id` bigint DEFAULT NULL,
  `ancestors` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='票据库存表';

